package com.parkgrid.web;
import com.parkgrid.domain.*;import com.parkgrid.repo.*;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import java.time.*;import java.util.*;
@RestController @RequestMapping("/api/bookings")
public class BookingController {
 private final BookingRepository bookings;private final ParkingSlotRepository slots;private final UserRepository users;
 public BookingController(BookingRepository b,ParkingSlotRepository s,UserRepository u){bookings=b;slots=s;users=u;}
 public record Request(@NotNull Long slotId,@FutureOrPresent Instant startTime,@Future Instant endTime){}
 @PostMapping @Transactional public Map<String,Object> book(@Valid @RequestBody Request r,java.security.Principal principal){if(!r.endTime().isAfter(r.startTime()))throw new IllegalArgumentException("endTime must be after startTime");ParkingSlot s=slots.findByIdForUpdate(r.slotId()).orElseThrow();if(s.getStatus()==ParkingSlot.Status.MAINTENANCE)throw new IllegalStateException("Slot unavailable");if(!bookings.findOverlaps(r.slotId(),r.startTime(),r.endTime()).isEmpty())throw new IllegalStateException("Slot is already booked for this period");long hours=Math.max(1,(r.endTime().getEpochSecond()-r.startTime().getEpochSecond()+3599)/3600);long amount=hours*s.getZone().getRateCents();Booking b=bookings.save(new Booking(users.findByEmail(principal.getName()).orElseThrow(),s,r.startTime(),r.endTime(),amount));s.setStatus(ParkingSlot.Status.RESERVED);return Map.of("bookingId",b.getId(),"slotId",s.getId(),"amountCents",b.getAmountCents(),"ratePerHourCents",s.getZone().getRateCents(),"status",b.getStatus());}
 @GetMapping("/mine") public List<Booking> mine(java.security.Principal p){return bookings.findByUserEmailOrderByStartTimeDesc(p.getName());}
 @PostMapping("/{id}/cancel") @Transactional public Map<String,Object> cancel(@PathVariable Long id,java.security.Principal p){Booking b=bookings.findById(id).orElseThrow();if(!b.getUser().getEmail().equals(p.getName()))throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.FORBIDDEN,"Only the booking owner can cancel it");if(b.getStatus()!=Booking.Status.CONFIRMED)throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.CONFLICT,"Only confirmed bookings can be cancelled");b.setStatus(Booking.Status.CANCELLED);if(bookings.countBySlotIdAndStatus(b.getSlot().getId(),Booking.Status.CONFIRMED)==0)b.getSlot().setStatus(ParkingSlot.Status.AVAILABLE);return Map.of("bookingId",id,"status",b.getStatus(),"message","Booking cancelled successfully");}
}
